// app/actions.js
'use server';

import { revalidatePath } from 'next/cache';

export async function createNote(formData) {
  const title = String(formData.get('title') || '').trim();
  if (title.length < 3) return { error: 'Enter at least 3 characters.' };
  // Authenticate, authorize, and persist using the app's trusted data layer here.
  revalidatePath('/notes');
  return { success: true };
}
